import json

with open('data/modern-translation/t1251_part2.json', 'r', encoding='utf-8') as f:
    modern = json.load(f)

# 段61
modern[61] = "【八大壇觀與聖者印】以上就是八大曼荼灌的樣式、觀念與造作方法。像這樣有智慧的行者以智慧通達曼陀羅中妙藏世界的因緣，一切聖尊都會前來，這個壇成就法就是瑜伽道場。行者以觀智通達這個世界相時，就能成就一切法、滿足一切大願。聖者印的結法：左右手的地指（小指）又伏壓水指（無名指）各自收進掌內，左右手的空指（大拇指）各自貼在水指尖上，左右手的火指（中指）直立如柱指尖不合而交叉豎直，左右手的風指（食指）朝向天壇方向指尖相合豎直，用這個印印五處。【义解】本段總結八大曼荼羅的造壇、觀想方法，說明通達壇法即得瑜伽相應、聖眾降臨、滿足諸願；隨後講授聖者（本尊）總印的詳細結法，以及印五處的用法。"
# 段62
modern[62] = "【聖者根本大真言】彼大真言王說：「曩莫三滿多菩駄南（一）　唵縛日羅（二合）薩羅曩（二）誐多𭕚（二合）吽增󰽫羅三限吽（二合）索婆訶」「依靠這個真言印的加持，真言行者的身體就和金剛薩埵等身體同等，對此不要有任何懷疑，諸佛都會歡喜加持這個功德。【义解】本段給出聖者印對應的大真言，並宣說此印明的廣大功德：令行者身同金剛薩埵，獲得諸佛加持，無有疑惑。"
# 段63
modern[63] = "【如意寶珠真言】如果是為了治病，這個法就成為良藥；如果是一切所有物，就成為如意寶珠，又能成就一切法。如意寶珠明說：「曩謨三滿多菩多喃（一）　麼賀（引）阿羅（引）闍野（二）　唵皿𭤶（三）　蘇母多羅（三）　旃荼縛薩羅（二合）羯羅枳哩矩嚕主魯沙眤（四）【义解】本段宣說聖者印明的萬能功德：治病為藥、滿願為如意寶珠、能成一切法；隨後給出如意寶珠真言，是本法中增益滿願、賜予財富的核心真言。"
# 段64
modern[64] = "【如意寶珠印與行法】「達摩（二合）馱都娑婆訶」「印相：各個手結金剛拳，各個火指（中指）指尖收入掌中，分別放在兩膝上，就觀想是如意寶珠。如果持這個法的人，要對一切眾生發起慈悲心念，不要生起瞋恨、誑騙、諂媚、害他的心，如果起了瞋心就會失去大神驗，要恆常守護自心不要起瞋恚。又持這個咒的人，每天要憶念我多聞聖者以及我的眷屬、讚歎我們，恆常以十善業道共同相助，助我證得菩提。【义解】本段圓滿如意寶珠真言，講授對應的印相（金剛拳置膝、觀寶珠），並強調修法的核心戒律：對眾生慈悲、不起瞋恚、常憶念本尊與眷屬、行十善，否則會失去法驗。"
# 段65
modern[65] = "【持法現世功德】由於憶念這些天眾，他們知道這件事之後，都會大生歡喜，一起前來護持行者。這個持咒的人、持真言的人，壽命長遠能經無量歲，永遠遠離三惡道，永無災難橫厄，又能獲得如意寶珠以及地下伏藏，神通自在，所有願望都能成就。如果求官職榮位，沒有不稱心如意的。又能解一切禽獸的語言。【义解】本段宣說如法受持如意寶珠法的現世功德：長壽、離惡道、無災、得寶藏、神通自在、滿願、得官祿、能解禽獸語，是非常廣大的現世利益。"
# 段66
modern[66] = "【地輪觀想次第】以上是這個真言的功德，大略就是這樣。行者如果想要作法，首先應當整理曼荼羅地。首先直心合掌，以三昧心進入三昧地，沒有其他雜念。思惟這大地的樣子：首先有空輪，顏色駁雜形狀圓形，以欠字作為種子字莊嚴。接著觀想風輪，顏色黑色形狀是半月形，以吽（二合）字作為種子。【义解】本段開始講地大觀（地輪種子字觀）的次第：首先入三昧無雜念，從空輪（種子欠、雜色圓形）開始觀，依次觀風輪（種子吽、黑色半月形），是構建金剛地的觀法基礎。"
# 段67
modern[67] = "【四大輪觀種子】接著思惟火輪，形狀是三角形、顏色赤色，以羅阿（二合）字為種子。接著觀想水輪，種子是鑁字，顏色白色形狀圓形。接著觀想地輪，形體是方形、顏色黃色，以阿字作為它的大種子。應當在心中默念那個觀想的三摩地明。真言說：「曩謨三滿多菩馱南（一）　唵（二）【义解】本段接續四大輪的觀想：火輪（種子囉（羅阿）、赤色三角）、水輪（種子鑁、白色圓形）、地輪（種子阿、黃色方形），四大輪觀完畢，給出地輪加持的三摩地真言。"
# 段68
modern[68] = "【金剛地觀成就】「欠󱁥藍鑁阿娑婆訶（引）」「接著觀想這個八大曼荼羅地，這樣就是金剛不破的世界，是諸尊常住的世界，也就是清淨法界。大天王從他的北方有一座城，名叫阿尼曼陀。這座城以七寶構成，是極其堅固不破、諸尊常住的世界，是無比微妙的世界，大天就住在這個世界。【义解】本段圓滿四大種子真言，說明觀想四大輪之後，壇地就成為金剛不破的清淨法界、諸尊常住的聖地；同時觀想本尊多聞天王所居住的七寶城阿尼曼陀，明瞭本尊的住處。"
# 段69
modern[69] = "【請本尊降臨偈】只要能結印誦真言，不違背三昧耶戒，天王一定會來到這個曼荼羅，令一切眾生的大願都得成就。就誦請吽迦陀野的偈頌，頌說：「敬禮諸佛　敬禮天等　唯願大王　此方下向　下向力故　護持壇等　所願滿足」「又結淨堂內印，左右手的地指、水指都各自收進掌內，又各自用空指（大拇指）按在地指、水指三指中間，左右手的火指（中指），左手火指根貼右手火指尖，右手火指根貼左手火指尖。【义解】本段講只要結印誦咒、不犯三昧耶戒，本尊必定降臨滿願；給出請本尊的短偈，隨後講淨道場（堂內）印的詳細結法，用來清淨道場內部。"
# 段70
modern[70] = "【淨道場印真言】就這樣，左右手的風指做成寶形，堂內就得到清淨，再印五處就完成了。依靠這個真言印，道場（堂內）所有的地方都得到清淨，不會有惡蟲等災難。真言說：「曩謨三滿多菩持喃（二）　阿跛利多野（二合引）誐誐曩三摩三摩抳野吽（三）　發吒」「接著是寶莊嚴堂內印，左右手放在頭上，隨著娑婆訶的聲音來去動作。【义解】本段補充淨道場印的風指要點（作寶形）、用法（印五處）與功德（淨場、除惡蟲），給出對應真言；隨後引出莊嚴道場的寶莊嚴印，結印位置在頭頂，配合真言動作。"
# 段71
modern[71] = "【寶莊嚴治路印】真言說：「唵（一）　三麼耶（二）　吽（三）（引）」「接著結治路印，左右手結內縛，地指、水指二指交叉橫臥，二火指頭合併直立，二風指向左右伸直伏下，右火指尖用左空指按著，左火指尖用右空指按著，先印五處，然後放在壇中。真言說：「曩謨三滿多冒馱喃（一）【义解】本段給出寶莊嚴道場印對應的真言；隨後講治路印（淨化行道道路）的詳細結法、操作順序（先印五處，再放壇中），並引出治路印的真言。"
# 段72
modern[72] = "【結界四天王印】「阿（二合）誐尼野度嚧吽發吒」「接著結四大天王結界印：二手的小指屈入掌中，右押左豎起，二中指、無名指相離一寸，二頭指（食指）相柱，二大指都屈入掌內。真言說：「唵婆帝也畔馱含吽（一）　𭤶菩溥娑婆賀（引）」「依靠結這個印，一切諸惡全都散向遠方。【义解】本段圓滿治路印真言，接著講四大天王結界印的詳細結法、對應真言，以及功德：驅散一切惡障，令道場外圍堅固守護。"
# 段73
modern[73] = "【四天王召請印】這個印上下各動三次。接著結四天王印：先把右手叉腰，豎起風指（食指），用左手小指押著大拇指，其餘三指豎立放在肚臍上。持咒的人應當現出惡意的忿怒相。真言說：「唵嚧迦婆唎泥（一）　社野社野社耶（二）　吽索婆賀（引）」「用這個印和真言請四天王，他們就會從遠處前來，做最殊勝的擁護。【义解】本段補充四大天王結界印的動作次數（上下三次），隨後講召請四天王的印相（右手叉腰豎食指、左手按臍現忿怒相）、對應真言，以及功德：四天王降臨守護道場。"
# 段74
modern[74] = "【吉祥天瑜伽印】「接著結摩訶室利提婆毘瑜伽成辦所修法之印。二手合掌，二大拇指並立，在風指旁邊離開一寸左右，微微彎曲兩個小指尖相押，水火二指各屈指頭，相距如鉤形就完成了。七寶迦摩羅真言說：「唵毘摩羅（一）　𮓌娑羅伐底（二）　三婆羅吽（三）【义解】本段講大吉祥天女瑜伽成辦法的印相結法、對應的七寶真言，這個印用來和吉祥天相應，成辦增益、敬愛等一切所修事業。"
# 段75
modern[75] = "【使者天女召請印】」接著應當結使者天女等印。彎曲右手掩在左手上肘後面，伸長頸項，身體微微彎曲朝向地面，誦這個真言。明說：「唵阿竭竭儞（一）　但地囉（二）　滿遮吒訶悉作（三）　吽發吒作吽」「結這個印，就是請金剛使者提婆毘等，他們都會大生歡喜，迅速來到咒師所在之處。【义解】本段講召請使者天女的印相（右手掩左肘、伸頸俯身）、動作與對應真言，能令金剛使者天女歡喜迅速降臨，供行者差遣。"
# 段76
modern[76] = "【使者降臨成辦事】來到之後就隨行者心意，一切所作的法事全都能成就。「接著結請三昧耶印。先合掌十指在內相叉，二水指（無名指）豎直指尖相柱，二風指（食指）豎起微微彎曲，左空指（大拇指）進入右掌中押左火指的指甲，右空指越過左空指背面進入左掌中押火指指甲，二風指隨著「訶」的聲音做招喚的動作。真心持這個印法，就是請召界會聖眾的印。【义解】本段說明使者降臨後一切事業成就，隨後講三昧耶請聖印的詳細結法、招喚動作，這是通用的召請曼荼羅全體聖眾的印契。"
# 段77
modern[77] = "【三昧耶請聖真言】真言說：「曩謨三滿多󰂛馱喃（一）　唵（二）　唵（三）　吠室囉麼那野（四）　曳醯呬（五）　索博賀（引）」「依靠這個印以及誦真言七遍，天王和眷屬就會降臨壇場，天王就會以慈悲心就座接受小供養，所請來的眷屬等也各就本來的座位接受我的供養。【义解】本段給出三昧耶請聖印對應的真言，說明持印誦咒七遍的功效：本尊毘沙門天王與眷屬全體降臨壇場，各自入座接受供養。"
# 段78
modern[78] = "【奉請聖眾證明】接著胡跪，手取香爐對著天王面前，至心奉請所有眷屬夜叉、羅剎，以及大日、釋迦等諸佛菩薩、金剛力士降臨道場，為我做證明。在北方毘沙門天王的道場中，得成就法門，獲得身神通力，得大自在，所願都能隨心滿足。「接著是飲食印。左右手結內縛，各個地指（小指）豎起指尖相對而立，左右內縛打開，距離五寸、一寸或三寸。【义解】本段講胡跪拈香、至心奉請三寶與護法降臨證明的行法，說明在毘沙門道場修法可得神通自在、滿足諸願；隨後引出奉供飲食的印契結法，進入供養環節。"
# 段79
modern[79] = "【飲食上味供養印】奉供真言說：「曩謨三滿多縛日羅（二合）赦吽尾訖梨𭻼度佉多𤙖（引）」「接著結上味印。左右手結內縛，左右風指（食指）在中節旁邊交叉豎直，指尖如水牛角一樣。奉供真言說：「南無尾秫多佉（二合引）野󰿀醯縛野（一）　吽發吒（引）【义解】本段給出飲食供養印對應的奉食真言；隨後講上味（美味飲食）供養印的結法（內縛、風指叉豎如水牛角）與對應的上味供養真言，完成美食供養的印明。"
# 段80
modern[80] = "【甘露王印明】索縛佉（引）」「接著是甘露王印。左右手的水指、火指合併做成寶形，兩個空指（大拇指）在兩指中間相柱，如兩隻姣好的形狀豎立，二地指、二風指都分開如柱直立姣好，大約一百遍左右隨意令其轉迴。真言說：「唵多毘（引）智野吽（一）　那索佉野尾秫第（三）【义解】本段接上味真言，講甘露王印（加持飲食成甘露）的結法、轉動次數（百遍），並引出甘露真言，用來加持供品成為甘露妙食。"
# 段81
modern[81] = "【法輪供養印】「吽誐誐曩（四）　三麼三麼（五）　吽（六）　吽（七）　發吒娑縛賀（引）」「接著是大法全轉印（法輪供養印）。左右手的地指、風指分開如水牛角，左右空、水、火三指屈入掌中，左手在上、右手向上，左右手的地指、風指指尖合在一起，右火指尖貼左地、風指，左火指尖貼右地指尖。【义解】本段圓滿甘露王印真言，隨後講大法輪轉供養印的結法，這個印象徵轉大法輪供養聖眾，是供養中的重要印契。"
# 段82
modern[82] = "【法輪與都合印】奉迴（法輪供養）明說：「南謨難机𮛳佉那野（一）　吽發吒索溥訶」接著應當結大密十二都合印。二手結內縛，在頂上向四方上下牽引。真言說：「唵󱂧梨含吽（二合引）」「接著是示現住自在八曼陀羅印。二手合掌，八個風、水指向外橫臥如牙，這就是大寶一切成滿、無所不至的印。【义解】本段給出法輪供養印對應的真言；隨後講大密十二都合印的結法（內縛、頂上向四方牽引）與真言；再引出八曼荼羅自在成滿印，結法是合掌、風水指外橫如牙，能成滿一切事業。"
# 段83
modern[83] = "【八曼陀羅成滿印】明說：「唵嚩日羅（二合）鉢那麼三昧耶（一）　薩怛鑁（二合）吽」「接著現三種身。讚說：「唵嚩日囉（二合）曩（引）娑野泥伊（二合引）嚩（一）　婆娑羅（二合）滿耶太那野（引）南無卒都帝（引入）【义解】本段給出八曼陀羅成滿印對應的真言，隨後講三種身（法報化三身）的顯現，並給出對應的讚嘆真言。"
# 段84
modern[84] = "【三身讚嘆真言】摩迦（引）麼娑野（引）伊多都耶佉野（二合引入）曩迷（引）索伽多野（引入）娑冒跢尼焱（引）野𤿺𭔻多（上引）滿多曩（音引）娑焱野𮏸智（引）佉多（引）瞿尼野（引）曩漠卒都帝（引入）唵（一去）【义解】本段是三身讚嘆真言的中間部分，為梵文密咒，原字保留，用來讚嘆三身，令本尊歡喜加持。"
# 段85
modern[85] = "【三身讚咒圓滿】嚩日羅（二合）入（目返）婆羅（二合引）嚩日羅阿（引上）嚩娑羅（引）佉多（鈴鳴如引）尼（入）婆（入）薩（上）𭔼（引）佉㝹佉野（二合引）𭕁多野蘇󰽫羅（引）阿野滿哆婆喃（引）索多（去引）【义解】本段是三身讚嘆真言的後半部分，密咒原字保留，至此讚嘆三身的真言圓滿。"
# 段86
modern[86] = "【三部部母分別】」「曩多（去）曩謨誐野（引）曩謨卒都帝（引）」八大曼荼羅的行相已經說完了。這八大漫荼羅有部母，分為三身，也就是所謂大日佛部、觀音蓮華部、不動尊金剛部。毘沙門王屬於佛部，八牙天和他同部；吉祥天、證入界等屬於蓮華部；【义解】本段總結八大曼荼羅行相講畢，開始講三部部母的分類：佛部（大日、毘沙門、八牙）、蓮華部（觀音、吉祥天、證入界）、金剛部（不動、一面十臂本尊），是密教三部的歸攝。"
# 段87
modern[87] = "【三部部母真言】一面十臂本尊屬於金剛部。像這樣分別攝屬。佛部母真言說：「（𭬫󱄌一）　圓𮥟（二）」「也就是八大漫荼羅相中，𮥉字法入就是息災的樣式。接著蓮花部母真言說：「󱄠（一）　𭁁（二）」「也就是敬愛增益的形相。金剛部母真言說：「𭁃（一）【义解】本段完成三部的分類，分別給出佛部、蓮華部、金剛部的部母種子字真言，並說明各部對應的事業：佛部主息災，蓮華部主敬愛增益，金剛部主降伏。"
# 段88
modern[88] = "【種子字點相表法】「𭁁（𭆟瞐二）」「也就是阿毘遮盧迦火壇漫荼羅之相。那個󱃳字上面有五個口點，就是五如來的形相。父中的𭌖字，就是多聞王的形相。梨字上面放𭕂字，就是這個漂息災之相。另外蓮花部母的𮥎字上面沒有點，就是蓮花的形相。梨字上有一個花點，就是敬愛等相，也就是漂色。【义解】本段圓滿金剛部母真言，說明降伏法對應火壇；隨後解釋各部母種子字上的點畫所表法義：五點表五佛、不同點表息災/敬愛/降伏的差異，令行者理解種子字的觀想含義。"
# 段89
modern[89] = "【三部真言音聲法】金剛部有󱃴字，上面是三角點，就是金剛的形相。𮥟字上面又有一個三角點，就是這個阿毘遮迦（降伏）漂相。佛部真言，聲音是長引的樣子，󱃳字用長引音誦，梨字用長引音、向上提音誦。蓮花部的󱁬字用那個音，梨字用波浪音、婉轉長引。金剛部󱁬字音用粗猛灑脫的惡聲，𭢍字也和上面一樣。【义解】本段解釋金剛部種子字的三角點表金剛降伏相；隨後講三部真言誦念的音聲差異：佛部長引平靜，蓮華部婉轉波浪，金剛部忿怒粗猛，不同音聲對應不同事業的相應。"
# 段90
modern[90] = "【種子成壇觀喻】這就是三部母真言的音聲樣式。這八大法門，所有聖尊都從這裡流出。這三部當中，佛部真言󱃳、𮥟二字中間就是󱀨字，就是八大曼荼羅之相，以及供養法之相。在那個󱃳字上加五口點乃至林字。另外這八大世界的漂相，有大樹林：首先生出各種好葉，然後開花，然後結果，然後果實成熟，生出甘美林中各種味道，利益有情眾生。【义解】本段總結三部母真言的音聲規範，說明三部種子出生一切聖尊與壇法；用大樹林的生長順序（生葉→開花→結果→果熟出味）比喻修法的次第（發心→修行→成辦→利益眾生）。"
# 段91
modern[91] = "【修心次第喻林】然後多聞王就像那座大樹林。另外󱁬字就如同那座大樹林，這󱁬一個字，就是行者想要修真言心王的時候，就會生出大樹林。然後在心王中放置󱃳一字，念它就生出美好的青五色葉。然後修真言的人安住心王阿娑頗那伽三昧、不動心念八大道場的時候，就會生出好相具足的稀有花朵。【义解】本段接續大樹林比喻：多聞天王如同大樹林，種子字󱁬為種，修行中次第生葉（觀行增長）、開花（三昧現前、好相現前），對應修證的不同階段。"
# 段92
modern[92] = "【修行證果喻熟果】然後行人修真言供養諸尊以及大王的時候，就又結出果實。接著行者至心通達八大漫荼羅的意趣，誦真言王。想要所修的法成就，沒有其他雜念，思惟那尊的形相體。自心王城顯現安住的時候，所生的果實就成熟了。而後行者發起廣大無比的大慈三昧，將利益一切眾生所生的功德迴向給法界眾生，斷除他們的罪苦、煩惱、業障，三時念誦就成為甘味布施，隨順法界眾生每一個的罪業，都一一給予利益安樂，就誦這個󱃳字。【义解】本段接續樹林比喻：供養聖尊→結果，通達壇法、專念本尊→果熟（法成就）；隨後發大慈心，將功德迴向法界一切眾生，令其離苦得樂，是修行成熟後的菩提心行。"
# 段93
modern[93] = "【天王現前授記】本尊天王就會在行人面前顯現形體，對那人說：「我隨從你。」行人心裡沒有一點懷疑的念頭，這就是毘沙門天王體相的種子相。那五個口點，就是護持佛法僧三寶之相。也就是天王的本來三昧耶。他的心堅固，從中出生這五佛。而這五佛為了利益眾生，所以顯現在天王堅固的心中。【义解】本段講修行成就時本尊現前授記：天王親自現身承諾護持行者；解釋種子字五點表三寶與五佛，五佛從天王堅固菩提心中出生，彰顯天王與五佛不二。"
# 段94
modern[94] = "【種子字觀成就】行人像這樣通達了知󱃳字的相狀，如法以觀智成就這個大心王法。這兩個字就是種子曼陀羅，也就是說行者觀想能夠這個法的󱄋字、梨字，就這樣成就種子曼陀羅了。另外蓮華、金剛各加上大點，就得到意字，心就如同那些點一樣漂現蓮華、金剛之相。𮥟字就如同大山，一切大小河、江、海都從這裡出生。【义解】本段總結種子字觀成就，說明佛部兩個種子字即種子曼荼羅，加上點就分別顯現蓮華、金剛部；同時用大山出生江河比喻𮥟字出生一切法，是吉祥天女的體相種子。"
# 段95
modern[95] = "【部母護摩總持】𮥟就是法入漫陀羅大事相的部母種子。𮥟字就是大吉祥女的體相，也就是念𮥟字，天女王就會現前站立，承事法師，這就是從𮥟字中顯現。另外一法就是護摩法，專一以𮥟字作為供養相應法。也就是這兩個字合起來作為曼陀羅的部母真言，從這兩個字中出生這個大密法。【义解】本段進一步解釋𮥟字（佛部母種子）是吉祥天女的體相，也是護摩法的核心種子；兩字合為部母真言，出生全部大密法。"
# 段96
modern[96] = "【部母真言功德】也就是行者口唱󱀨𮥟（二合）一遍，就能得到這樣的本誓，一一事業都成就圓滿，所以名叫曼陀羅母真言。如果想要供養這個曼荼羅，首先陳設供養具、初始發誓，行者首先要至心好好聞受憶持，為了未來有情可以傳授。想要修法的時候，首先應當準備供養相應的物品，在淨室中用瞿摩夷（牛糞）塗地，作大壇相應的壇場。【义解】本段講部母二合真言的功德：誦一遍即得本尊本誓加持，一切事業圓滿，所以稱為曼陀羅母；隨後講供養曼荼羅的準備工作：準備供具、清淨塗地、築造壇場。"
# 段97
modern[97] = "【供品準備清淨】並且還要用金、木、土、葉、螺等材質的器具，按照時節準備飲食、時令果子、時花、香油、燈、蘇油煎餅、乳粥等，酪、蘇、蜜、𩚈捻頭子團、各種甘味團、粥菜各種食物團，時草、時令美味以及小點心等，餅、飯、各種甘美果子，各種和合製作的藥，各種香味的歡喜丸，如法清淨、至心供養。【义解】本段詳細列舉供養所需的各類供品：各種材質的器具，飲食、果子、花香、油燈、乳粥、酪蜜、點心、歡喜丸等，要求如法清淨、至心奉獻。"
# 段98
modern[98] = "【燒香與護身線】要常燒妙香、各種名香，也就是安息香、旃檀、龍腦、蘇合香、多揭羅香、薰陸香、松香等。全部等量混合，在一個香爐中燒。還要用真言加持白線以及五色線，把這條線繫在身上，一切事業必定成就。首先要敬禮三寶以及多聞伽陀野王，才開始行法。【义解】本段講供養中的燒香：列舉七種名香等量和合焚燒；同時講用真言加持五色線、白線繫身（護身線），能令事業成就；行法前首先要敬禮三寶與本尊。"
# 段99
modern[99] = "【童子預告成就】在這中間要觀想：依靠這個功德力，能夠令一切眾生的所有願望都得成就。這樣念完、禮拜完開始作法，香煙不要斷絕，誦前面的母咒等，晝夜繫念，不要讓其他人知道。那時多聞王有個兒子，名叫禪膩師，現童子形來到這個地方，問道：「你為什麼呼喚我父親？」就回答他說：「我為了供養三寶，為了供養、滿足一切願望，所以請他。」【义解】本段講行法中的觀想（功德施眾生）、精進要求（香不斷、晝夜持咒、保密）；同時講修法將要成就時的驗相：多聞天王的兒子禪膩師現童子身前來詢問，為成就的預兆。"
# 段100
modern[100] = "【啟白父王驗相】那時童子聽完之後，就回到本宮稟告父親說：「現在有善人發誠心供養三寶，要滿足一切願望，以諸念事請您。」他的父親回覆兒子說：「你趕快到那裡對他說：『你說每天施一百迦利沙波拏（金幣），乃至滿十陳那羅的數量。』」持咒的人見到這個相狀之後，就知道法可以成就了。【义解】本段接續成就驗相：童子回去稟告父王，父王傳語要求每日布施，行者見此驗相即知法將成就，是修法過程中的感應標誌。"

